sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_progress;
uniform float amzp_style;
uniform float amzp_grid;
uniform float2 amzp_origin;
uniform float amzp_strength;
uniform float amzp_gravity;
uniform float amzp_rotation;
uniform float3 amzp_sceneRotation;
uniform float amzp_randomness;
uniform float amzp_seed;
    float hash(float2 p) {
        float3 p3 = fract(float3(p.xyx) * .1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float2x2 rot2(float a){ float s = sin(a), c = cos(a); return float2x2(c,-s,s,c); }
    float3x3 rotX(float a) { float c=cos(a), s=sin(a); return float3x3(1,0,0, 0,c,-s, 0,s,c); }
    float3x3 rotY(float a) { float c=cos(a), s=sin(a); return float3x3(c,0,s, 0,1,0, -s,0,c); }
    float3x3 rotZ(float a) { float c=cos(a), s=sin(a); return float3x3(c,-s,0, s,c,0, 0,0,1); }
    float3x3 transpose3(float3x3 m) {
        return float3x3(
            m[0][0], m[1][0], m[2][0],
            m[0][1], m[1][1], m[2][1],
            m[0][2], m[1][2], m[2][2]
        );
    }
    float3x3 getRot3D(float3 r) {
        float3 rad = radians(r);
        return rotY(rad.y) * rotX(rad.x) * rotZ(rad.z);
    }
    float iSphere(float3 ro, float3 rd, float r) {
        float b = dot(ro, rd);
        float c = dot(ro, ro) - r*r;
        float h = b*b - c;
        if(h < 0.0) return -1.0;
        return -b - sqrt(h);
    }
    float2 iBox(float3 ro, float3 rd, float3 boxSize, out float3 outNormal) {
        float3 m = 1.0 / rd;
        float3 n = m * ro;
        float3 k = abs(m) * boxSize;
        float3 t1 = -n - k;
        float3 t2 = -n + k;
        float tN = max(max(t1.x, t1.y), t1.z);
        float tF = min(min(t2.x, t2.y), t2.z);
        if(tN > tF || tF < 0.0) return float2(-1.0);
        outNormal = -sign(rd) * step(t1.yzx, t1.xyz) * step(t1.zxy, t1.xyz);
        return float2(tN, tF);
    }
    struct Shard {
        float2 disp;
        float rot;
        float2 pivot;
        float depth;
        float scale;
        float3x3 rot3d;
        float2 uvOffset;
    };
    Shard getShard(float2 cid, int k, float t, float g) {
        Shard S;
        float2 cellCenter = (cid + 0.5) * g;
        float rnd = hash(cid + float2(float(k)*1.23, float(amzp_seed)));
        S.uvOffset = float2(hash(cid + rnd), hash(cid - rnd)) - 0.5;
        S.pivot = cellCenter / screen.zw;
        float2 centerPx = amzp_origin * screen.zw;
        float2 dir = cellCenter - centerPx;
        float d = length(dir);
        float2 normDir = dir / max(d, 1.0);
        float angleVar = (rnd - 0.5) * amzp_randomness * 2.0;
        normDir = rot2(angleVar) * normDir;
        float forceMag = amzp_strength * 500.0 * (1.0 + (rnd - 0.5) * amzp_randomness);
        float2 vel = normDir * forceMag;
        float2 grav = float2(0.0, -amzp_gravity * 1000.0);
        float amzLocal_time = t * 2.0;
        S.disp = (vel * amzLocal_time + 0.5 * grav * amzLocal_time * amzLocal_time) / screen.zw;
        S.rot = radians(amzp_rotation) * amzLocal_time * (rnd - 0.5) * 2.0;
        float bZ = (int(amzp_style) == 5) ? -3.0 : 1.0;
        S.depth = amzLocal_time * (rnd + 0.5) * bZ;
        S.scale = 1.0 / (1.0 + max(S.depth, -0.9) * 0.5);
        float3 worldRot = float3(0.0, 0.0, degrees(S.rot)) + amzp_sceneRotation;
        S.rot3d = getRot3D(worldRot);
        return S;
    }
    float4 checkPiece(float2 cidC, int k, float t, float g, float2 uvNow, out bool found, out float dOut) {
        Shard S = getShard(cidC, k, t, g);
        float aspect = screen.zw.x / screen.zw.y;
        if (int(amzp_style) <= 1 || int(amzp_style) == 5) {
            float2 uv0 = uvNow - S.disp;
            float2 pRel = uv0 - S.pivot;
            pRel.x *= aspect;
            pRel /= S.scale;
            pRel = rot2(-S.rot) * pRel;
            pRel.x /= aspect;
            uv0 = pRel + S.pivot;
            float2 px0 = uv0 * screen.zw;
            float2 cid0 = floor(px0 / g);
            float2 q = fract(px0 / g);
            bool matchCell = length(cid0 - cidC) < 0.1;
            bool isGlass = (int(amzp_style) == 1 || int(amzp_style) == 5);
            bool insideShape = (!isGlass) ? true : ((k == 0) ? (q.x + q.y < 1.0) : (q.x + q.y >= 1.0));
            found = matchCell && insideShape;
            if (found) {
                float4 col = amzTexture(0, clamp(uv0, 0.0, 1.0));
                if (col.a < 0.01) { found = false; return float4(0.0); }
                dOut = S.depth;
                return col;
            }
            return float4(0.0);
        } else {
            float3 ro = float3((uvNow - S.pivot), -1.0);
            ro.x *= aspect;
            ro.xy -= S.disp * float2(aspect, 1.0);
            ro.z -= S.depth;
            float3 rd = normalize(float3(0.0, 0.0, 1.0));
            float3x3 invRot = transpose3(S.rot3d);
            float3 roL = invRot * ro;
            float3 rdL = invRot * rd;
            float dHit = -1.0;
            float3 normal = float3(0.0, 0.0, -1.0);
            float shardSize = (g / screen.zw.y) * 0.5;
            if (int(amzp_style) == 2 || int(amzp_style) == 4) {
                float zThick = (int(amzp_style) == 4) ? shardSize * 0.2 : shardSize;
                float3 bSize = (int(amzp_style) == 4) ? float3(shardSize, shardSize, zThick) : float3(shardSize);
                float2 res = iBox(roL, rdL, bSize, normal);
                if (res.x > 0.0) dHit = res.x;
            } else if (int(amzp_style) == 3) {
                dHit = iSphere(roL, rdL, shardSize);
                normal = normalize(roL + rdL * dHit);
            }
            if (dHit > 0.0) {
                float3 pHit = roL + rdL * dHit;
                float3 worldNormal = S.rot3d * normal;
                float2 uv0 = (pHit.xy / (shardSize * 2.0)) + 0.5;
                float2 sampleUV = S.pivot + (uv0 - 0.5) * (g / screen.zw);
                float4 col = amzTexture(0, clamp(sampleUV, 0.0, 1.0));
                if (col.a < 0.01) { found = false; return float4(0.0); }
                float3 lightDir = normalize(float3(0.5, 0.5, -1.0));
                float diff = max(dot(worldNormal, lightDir), 0.0);
                float ambient = 0.4;
                col.rgb *= (ambient + (1.0 - ambient) * diff);
                found = true;
                dOut = S.depth + dHit * 0.1;
                return col;
            }
        }
        found = false;
        return float4(0.0);
    }
    void amzRender() {
        if (amzp_progress <= 0.001) {
             amzOutput = amzTexture(0, amzScreenNorm());
             return;
        }
        float2 uv = amzScreenNorm();
        float g = max(amzp_grid, 5.0);
        float2 px = uv * screen.zw;
        float2 baseCid = floor(px / g);
        float t = amzp_progress;
        int R = int(min(2.0 + amzp_strength * t * 20.0, 10.0));
        float4 bestCol = float4(0.0);
        float minDepth = 10000.0;
        bool hit = false;
        float2 winnerCid = float2(0.0);
        int winnerK = 0;
        int kMax = (int(amzp_style) == 1 || int(amzp_style) == 5) ? 2 : 1;
        for (int y = -R; y <= R; y++) {
            for (int x = -R; x <= R; x++) {
                 float2 cidC = baseCid + float2(float(x), float(y));
                 for (int k = 0; k < kMax; k++) {
                     bool found;
                     float dHit;
                     float4 res = checkPiece(cidC, k, t, g, uv, found, dHit);
                     if (found) {
                         if (dHit < minDepth) {
                             minDepth = dHit;
                             hit = true;
                             bestCol = res;
                         }
                     }
                 }
            }
        }
        if (hit) {
            amzOutput = bestCol;
        } else {
            amzOutput = float4(0.0);
        }
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
